          "pop": {{ faker 'number.float' min=0 max=1 }},
          "sys": {
              "pod": "{{ lookup (array 'd' 'd' 'n' 'n') (mod this 4) }}"
          },
          "dt_txt": "2025-09-{{ add 27 ../this }} {{ lookup times @index }}:00:00"
